from security_lab import parse_update
assert parse_update({'title':' Notes '}) == {'title':'Notes'}
# {'title':'Notes','owner':'alice'} is rejected, not mass-assigned.

def review(headers):
    h = {k.lower(): v for k, v in headers.items()}
    findings = []
    csp = h.get('content-security-policy', '')
    if not csp:
        findings.append('missing Content-Security-Policy')
    else:
        if "'unsafe-inline'" in csp and 'nonce-' not in csp:
            findings.append("CSP allows inline script without a nonce")
        if 'frame-ancestors' not in csp:
            findings.append('CSP does not restrict framing (frame-ancestors)')
    if 'max-age=' not in h.get('strict-transport-security', ''):
        findings.append('missing Strict-Transport-Security max-age')
    if h.get('x-content-type-options', '').lower() != 'nosniff':
        findings.append('missing X-Content-Type-Options: nosniff')
    if h.get('referrer-policy', '') in ('', 'unsafe-url', 'no-referrer-when-downgrade'):
        findings.append('Referrer-Policy leaks full URLs')
    return findings or ['ok']

weak = {'Content-Security-Policy': "script-src 'self' 'unsafe-inline'"}
strong = {
    'Content-Security-Policy': "default-src 'self'; script-src 'self' 'nonce-r4nd0m'; "
                               "object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
    'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
    'X-Content-Type-Options': 'nosniff',
    'Referrer-Policy': 'strict-origin-when-cross-origin',
}
for name, headers in (('weak', weak), ('strong', strong)):
    print(name, review(headers))

# Expected output:
# weak ['CSP allows inline script without a nonce', 'CSP does not restrict framing (frame-ancestors)', 'missing Strict-Transport-Security max-age', 'missing X-Content-Type-Options: nosniff', 'Referrer-Policy leaks full URLs']
# strong ['ok']

